"""Beta RX and Ducati Desmo450 MX wiring from the makers' own diagrams (owner-supplied 2026-11-26).
Component lists come from each diagram's printed legend (docs/research/electrical/beta-diagram-legends.json).
The RX 450 (2024-2026) and Desmo450 MX wire colours were read by eye, medium confidence. Not stored.
usage: python3 scripts/knowledge/wiring6.py"""
import sys,os,json
sys.path.insert(0,os.path.join(os.path.dirname(os.path.abspath(__file__)),'pre2020'))
from _lib import File,root
L=json.load(open(os.path.join(root,'docs/research/electrical/beta-diagram-legends.json')))
F=File('wiring6_beta_ducati','w-b1','Beta RX and Ducati Desmo450 MX wiring (wiring pass 2026-11)','Beta',['RX 450'],list(range(2021,2028)))
D='ecu_electronics';N='Read from the wiring diagram by eye; check the diagram on the bike before cutting, splicing or back-probing.'
KEY="Beta's wire colour letters are Italian: Bi white, Ve green, Ma brown, Vi purple, Bl blue, Ne black, Gi yellow, Rs red, Ar orange, Az sky blue, Ro pink, Gr gray. Two together mean base colour and stripe."
FILES={'2021_RX_300_2T':('RX 300',[2021]),'2022_RX_300_2T':('RX 300',[2022]),'2023_RX_300_2T':('RX 300',[2023]),'2024-2025_RX_300_2T':('RX 300',[2024,2025]),'2024-2026_RX_450_4T':('RX 450',[2024,2025,2026]),
 '2026_RX_250_2T_single_plug':('RX 250',[2026]),'2026_RX_350_2T_twin_plug':('RX 350',[2026]),'2027_RX_250_2T_single_plug':('RX 250',[2027]),'2027_RX_350_2T_twin_plug':('RX 350',[2027]),'2027_RX_450_4T':('RX 450',[2027])}
for f,(m,ys) in FILES.items():
    s=F.src('manufacturer',f"Beta {m} electrical diagram ({f.replace('_',' ')})",'https://betausa.com/support',str(ys[0]))
    comps=[c.capitalize().replace('µf','µF').replace('ω','ohm').replace('Ω','ohm') for c in dict.fromkeys(L[f])]
    yr=f"{ys[0]}" if len(ys)==1 else f"{ys[0]}-{ys[-1]}"
    F.R(D,'Wiring diagram: components and wire colour code',[m],ys,f"Beta's electrical diagram for the {yr} {m} shows: "+', '.join(comps)+". "+KEY,{'components':comps},'OEM',s,'high')
s=F.src('manufacturer','Beta RX 450 electrical diagram, 2024-2026','https://betausa.com/support','2024')
M=['RX 450'];Y=[2024,2025,2026]
F.R(D,'ECU connector pinout',M,Y,"ECU pinout on the 2024-2026 RX 450 (pin, wire colour, where it goes): 2 gray/blue and 19 gray/red, actuators relay and diagnostic side; 3 blue/black, sensor ground; 4 green and 14 red, pick-up; 6 yellow/blue, throttle position signal; 7 white/brown, temperature sensor; 9 white/pink, rollover sensor; 11 black, ground; 12 white/green and 24 yellow/white, T-MAP sensor signals; 13 green/red, 17 yellow, 18 orange/black and 28 white, stepper motor; 15 pink/purple, MIL warning light; 16 white/black, engine stop button; 20 gray/green and 36 yellow/red, second map switch; 21 brown/blue, gear sensor; 22 yellow/black and 34 yellow/pink, diagnostic connector; 23 gray, sensor supply; 25 gray/black, battery feed; 27 pink, injector; 29 red/blue, fuel pump; 30 green/black, generator connector; 35 white/red, ignition coil.",
 {'2':'Gr/Bl','3':'Bl/Ne','4':'Ve','6':'Gi/Bl','7':'Bi/Ma','9':'Bi/Ro','11':'Ne','12':'Bi/Ve','13':'Ve/Rs','14':'Rs','15':'Ro/Vi','16':'Bi/Ne','17':'Gi','18':'Ar/Ne','19':'Gr/Rs','20':'Gr/Ve','21':'Ma/Bl','22':'Gi/Ne','23':'Gr','24':'Gi/Bi','25':'Gr/Ne','27':'Ro','28':'Bi','29':'Rs/Bl','30':'Ve/Ne','34':'Gi/Ro','35':'Bi/Rs','36':'Gi/Rs'},'OEM',s,'medium',N+' Pin jobs are inferred from where each wire runs on the diagram.')
F.R(D,'Sensor, injection and switch wiring',M,Y,"Wire colours on the 2024-2026 RX 450. Sensors share a gray supply wire and a blue/black ground. Throttle position sensor: blue/black, yellow/blue signal, gray. T-MAP (pressure and air temperature) sensor: blue/black, yellow/white, white/green, gray. Temperature sensor: white/brown and gray. Rollover sensor: gray, white/pink and blue/black. Gear sensor: brown/blue, blue/black and gray. Pick-up: red and green. Injector: pink (ECU) and blue (power). Ignition coil: white/red (ECU) and blue (power). Fuel pump: blue/red and blue. Stepper motor on the throttle body: green/red, white, orange/black and yellow. Engine stop button: white/black to black (ground). Second map switch: yellow/red, blue and gray/green. Start button: gray/black and white/orange.",
 {'tps':'Bl/Ne, Gi/Bl, Gr','tmap':'Bl/Ne, Gi/Bi, Bi/Ve, Gr','temp':'Bi/Ma, Gr','rollover':'Gr, Bi/Ro, Bl/Ne','gear':'Ma/Bl, Bl/Ne, Gr','pickup':'Rs, Ve','injector':'Ro, Bl','coil':'Bi/Rs, Bl','fuel_pump':'Bl/Rs, Bl','stepper':'Ve/Rs, Bi, Ar/Ne, Gi','stop':'Bi/Ne, Ne','map_switch':'Gi/Rs, Bl, Gr/Ve','start':'Gr/Ne, Bi/Ar'},'OEM',s,'medium',N)
F.R(D,'Charging, battery and power feed',M,Y,"Power on the 2024-2026 RX 450: the stator sends two wires to the voltage regulator (white on the regulator side); the regulator's output is gray/black and its ground black. Gray/black is the battery positive feed throughout the bike, and it also runs to the 4,700 µF condenser, the start button, the MIL light and the actuators relay. The actuators relay switches power onto the blue wire that feeds the ignition coil, injector and fuel pump. The battery is a 12 V 2 Ah lithium unit with a 10 A fuse at the starter relay; the start button triggers the relay on white/orange. Black is ground. The MIL warning light sits in series with a 470 ohm resistor on pink/purple.",
 {'battery':'12 V 2 Ah lithium','fuse_a':10,'battery_feed':'Gr/Ne','switched_power':'Bl','ground':'Ne','condenser_uF':4700,'mil_resistor_ohm':470},'OEM',s,'medium',N)
G=File('wiring6_ducati','w-d1','Ducati Desmo450 MX 2026 wiring (wiring pass 2026-11)','Ducati',['Desmo450 MX'],[2026])
t=G.src('manufacturer',"Ducati Desmo450 MX owner's manual, electric system section (wiring diagram and key)",'https://www.ducati.com/','2025')
G.R(D,'Wiring diagram: components and wire colour code',['Desmo450 MX'],[2026],"Ducati's wiring diagram for the 2026 Desmo450 MX shows: ECU, start button, stop button, EFI light, map selector, ignition coil, gear sensor, injector, throttle position sensor, MAP sensor, air temperature sensor, coolant temperature sensor, pick-up sensor, ACG (alternator), voltage regulator, starter relay, main relay, remote control switch, battery, starter motor, fuel pump, diagnosis connector and ground points, plus optional connections and a BBS control unit with a speed sensor on bikes that have it. Ducati's wire colour letters: Y yellow, R red, Bk black, O orange, V purple, W white, Bn brown, G green, Gr gray, Lb light blue, B blue, P pink.",{},'OEM',t,'high')
G.R(D,'Shared wires and connector colours',['Desmo450 MX'],[2026],"On the 2026 Desmo450 MX diagram the sensors share a red/blue supply wire and a black/purple ground: the gear sensor, throttle position sensor and MAP sensor each carry both, and the air and coolant temperature sensors use black/purple as their ground. Red/white is the switched power feed to the injector, EFI light, map selector and fuel pump. Red is battery positive and black is ground. The alternator sends three yellow wires to the voltage regulator. The map selector carries red/white, gray/black, gray/green and black. The 5-pin diagnosis connector carries blue/black, gray/black, black, red and gray/green.",
 {'sensor_supply':'R/B','sensor_ground':'Bk/V','switched_power':'R/W','battery_positive':'R','ground':'Bk','alternator':'Y, Y, Y','map_selector':'R/W, Gr/Bk, Gr/G, Bk','diagnosis':'B/Bk, Gr/Bk, Bk, R, Gr/G'},'OEM',t,'medium',N+' ECU pin numbers are not legible on this copy and are not given.')
F.write();G.write()
